mapper.select:
SELECT COUNT(1)
FROM grant_table
WHERE role_code = #{roleCode}

mapper.delete:
DELETE
FROM grant_table
WHERE subject_type = #{subjectType}
  AND subject_id = #{subjectId}

mapper.select:
SELECT r.role_code, r.role_name, r.status, r.role_type, gt.grant_time FROM grant_table gt INNER JOIN sys_role r ON r.role_code = gt.role_code WHERE gt.subject_type = #{subjectType} AND gt.subject_id = #{subjectId} AND r.role_type IN
#{roleType}
ORDER BY r.role_code
